{"content":"def merge(intervals):
    """Merge half-open intervals [start, end).

    Returns a new sorted list of (start, end) tuples in which overlapping or touching intervals ([1, 3) and [3, 5))
    are joined. Empty intervals (start == end) are dropped. An interval with start > end raises ValueError. The input
    (any iterable of pairs) is not modified.
    """
    normalized = []
    for pair in intervals:
        start, end = pair
        if start > end:
            raise ValueError(f"invalid interval [{start}, {end}): start exceeds end")
        if start < end:
            normalized.append((start, end))

    normalized.sort()

    merged = []
    for start, end in normalized:
        if merged and start <= merged[-1][1]:
            prev_start, prev_end = merged[-1]
            merged[-1] = (prev_start, end if end > prev_end else prev_end)
        else:
            merged.append((start, end))
    return merged


def insert(intervals, new):
    """Add `new` to `intervals` and return the merged result."""
    return merge([*(intervals or ()), new])


def covered(intervals):
    """Total length covered by the intervals, overlaps counted once."""
    total = 0
    for start, end in merge(intervals):
        total += end - start
    return total


def gaps(intervals, lo, hi):
    """The parts of [lo, hi) no interval covers, as a sorted list of (start, end) tuples."""
    found = []
    cursor = lo
    for start, end in merge(intervals):
        if end <= cursor:
            continue
        if start >= hi:
            break
        if start > cursor:
            found.append((cursor, start if start < hi else hi))
        cursor = end if end > cursor else cursor
        if cursor >= hi:
            break
    if cursor < hi:
        found.append((cursor, hi))
    return found
